/* v5 srcdoc 방식 임베드 */
const _V5_B64 = "";
function getV5Html() {
  try {
    const raw = atob(_V5_B64);
    const arr = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i++) arr[i] = raw.charCodeAt(i);
    return new TextDecoder('utf-8').decode(arr);
  } catch(e) { console.error('v5 decode 오류:', e); return ''; }
}

