// 열려있는 프로젝트 ID 추적
let openProjId = { leader: null, member: null };
let activeProjId = { leader: null, member: null };

function toggleProjGroup(projId, role) {
  const toggle = document.getElementById((role==='leader'?'lpt-':'mpt-') + projId);
  const items  = document.getElementById((role==='leader'?'lpi-':'mpi-') + projId);
  if (!toggle || !items) return;

  const isOpen = toggle.classList.contains('open');
  // 다른 프로젝트 닫기
  PROJECTS_LIST.forEach(p => {
    if (p.id !== projId) {
      const ot = document.getElementById((role==='leader'?'lpt-':'mpt-') + p.id);
      const oi = document.getElementById((role==='leader'?'lpi-':'mpi-') + p.id);
      if (ot) ot.classList.remove('open');
      if (oi) oi.classList.remove('open');
    }
  });
  toggle.classList.toggle('open', !isOpen);
  items.classList.toggle('open', !isOpen);
  openProjId[role] = isOpen ? null : projId;

  // 첫 클릭 시 종합 대시보드 자동 열기
  if (!isOpen) {
    const firstItem = document.getElementById((role==='leader'?'lpitem-':'mpitem-') + projId + '-tab-dashboard');
    if (firstItem) openProjTab(projId, 'tab-dashboard', firstItem, role);
  }
}

function openProjTab(projId, tabId, el, role) {
  // 모든 항목 active 해제
  document.querySelectorAll(`#page-${role} .nav-proj-item`).forEach(i=>i.classList.remove('active'));
  document.querySelectorAll(`#page-${role} .nav-proj-toggle`).forEach(t=>t.classList.remove('active'));
  document.querySelectorAll(`#page-${role} .nav-item`).forEach(n=>n.classList.remove('active'));
  document.querySelectorAll(`#page-${role} .nav-sub-item`).forEach(n=>n.classList.remove('active'));

  // 현재 항목 active
  el.classList.add('active');
  const toggle = document.getElementById((role==='leader'?'lpt-':'mpt-') + projId);
  if (toggle) toggle.classList.add('active');

  activeProjId[role] = projId;
  const proj = PROJECTS_LIST.find(p=>p.id===projId);
  const tab  = PROJ_TABS.find(t=>t.tab===tabId);

  // 프로젝트 패널 표시
  const titleEl = document.getElementById(role+'-project-title');
  const subEl   = document.getElementById(role+'-project-sub');
  if (titleEl) titleEl.textContent = (tab?.icon||'') + ' ' + (tab?.name||tabId);
  if (subEl)   subEl.textContent   = proj ? proj.icon + ' ' + proj.name : '';
  const bc = document.getElementById('leader-proj-breadcrumb');
  if (bc && proj) bc.textContent = '수행 사업 / ' + proj.name;

  if (role === 'leader') {
    document.querySelectorAll('.ltab').forEach(t=>t.style.display='none');
    const panel = document.getElementById('ltab-project');
    panel.style.display = 'flex';
    const frame   = document.getElementById('leader-project-frame');
    const loading = document.getElementById('leader-iframe-loading');
    if (!frame.srcdoc) {
      loading.style.display='flex'; frame.style.display='none';
      leaderProjectTab = tabId;
      frame.addEventListener('load', onLeaderFrameLoad, {once:true});
      frame.srcdoc = getV5Html();
    } else {
      loading.style.display='none'; frame.style.display='flex';
      try {
        frame.contentWindow.postMessage({type:'switchTab', tab:tabId}, '*');
        // 신규 프로젝트 여부 (localStorage에 v4 데이터 없으면 isNew)
      const isNewProj = !localStorage.getItem('v4-proj-data-' + projId);
      frame.contentWindow.postMessage({
        type:'setProjectId', projId, isNew: isNewProj,
        projName:    proj?.name,
        projIcon:    proj?.icon,
        status:      proj?.status,
        startDate:   proj?.startDate,
        endDate:     proj?.endDate,
        desc:        proj?.desc,
        agency:      proj?.agency,
        host:        proj?.host,
        localGov:    proj?.localGov,
        partners:    proj?.partners || [],
        govFund:     proj?.govFund || 0,
        localFund:   proj?.localFund || 0,
        etcFund:     proj?.etcFund || 0,
        totalBudget: proj?.totalBudget || 0,
      }, '*');
      } catch(e){}
    }
  } else {
    document.querySelectorAll('.mtab').forEach(t=>t.style.display='none');
    const panel = document.getElementById('mtab-project');
    panel.style.display='flex';
    const frame   = document.getElementById('member-project-frame');
    const loading = document.getElementById('member-iframe-loading');
    if (!frame.srcdoc) {
      loading.style.display='flex'; frame.style.display='none';
      memberProjectTab = tabId;
      frame.addEventListener('load', onMemberFrameLoad, {once:true});
      frame.srcdoc = getV5Html();
    } else {
      loading.style.display='none'; frame.style.display='flex';
      try {
        frame.contentWindow.postMessage({type:'switchTab', tab:tabId}, '*');
        // 신규 프로젝트 여부 (localStorage에 v4 데이터 없으면 isNew)
      const isNewProj = !localStorage.getItem('v4-proj-data-' + projId);
      frame.contentWindow.postMessage({
        type:'setProjectId', projId, isNew: isNewProj,
        projName:    proj?.name,
        projIcon:    proj?.icon,
        status:      proj?.status,
        startDate:   proj?.startDate,
        endDate:     proj?.endDate,
        desc:        proj?.desc,
        agency:      proj?.agency,
        host:        proj?.host,
        localGov:    proj?.localGov,
        partners:    proj?.partners || [],
        govFund:     proj?.govFund || 0,
        localFund:   proj?.localFund || 0,
        etcFund:     proj?.etcFund || 0,
        totalBudget: proj?.totalBudget || 0,
      }, '*');
      } catch(e){}
    }
  }
}

// localStorage에서 권한 불러오기
function loadPermissions() {
  try { return JSON.parse(localStorage.getItem('projectPermissions') || '{}'); }
  catch(e) { return {}; }
}

function savePermsToDisk(perms) {
  localStorage.setItem('projectPermissions', JSON.stringify(perms));
}

function loadPermLog() {
  try { return JSON.parse(localStorage.getItem('permLog') || '[]'); }
  catch(e) { return []; }
}

function savePermLog(log) {
  localStorage.setItem('permLog', JSON.stringify(log.slice(-20)));
}

// 권한 뱃지 업데이트
function refreshPermBadges() {
  const perms = loadPermissions();
  ['김민수','이지현','박성호','최수연','정태양'].forEach(name => {
    const el = document.getElementById('perm-count-' + name);
    if (!el) return;
    const count = (perms[name] || []).length;
    if (count > 0) {
      el.className = 'perm-badge-count';
      el.textContent = count + '개 사업';
    } else {
      el.className = 'perm-badge-none';
      el.textContent = '미배정';
    }
  });
}

// ── 팀원 수행사업 사이드바 렌더링 (권한 기반) ──
function renderMemberProjectMenu() {
  const container = document.getElementById('member-biz-items');
  if (!container) return;
  const perms   = loadPermissions();
  const granted = new Set(perms[currentUser.name] || []);
  // 팀원에게 배정된 프로젝트만 필터
  const myProjects = PROJECTS_LIST.filter(p => granted.has(p.id));

  if (myProjects.length === 0) {
    container.innerHTML = '<div class="nav-sub-no-access">⛔ 배정된 사업이 없습니다<br><span style="font-size:10px">팀장에게 권한을 요청하세요</span></div>';
    return;
  }

  container.innerHTML = myProjects.map(proj => `
    <div class="nav-proj-group" id="mpg-${proj.id}">
      <div class="nav-proj-toggle" id="mpt-${proj.id}"
           onclick="toggleProjGroup('${proj.id}','member')">
        <span class="proj-icon">${proj.icon}</span>
        <span class="proj-name">${proj.name}</span>
        <span class="nav-proj-status ${proj.ps}">${proj.status}</span>
        <span class="proj-arrow">▼</span>
      </div>
      <div class="nav-proj-items" id="mpi-${proj.id}">
        ${PROJ_TABS.map(t => `
          <div class="nav-proj-item" id="mpitem-${proj.id}-${t.tab}"
               onclick="openProjTab('${proj.id}','${t.tab}',this,'member')">
            <span class="pi">${t.icon}</span>${t.name}
          </div>`).join('')}
      </div>
    </div>
  `).join('');
}

