window.addEventListener('DOMContentLoaded', renderTrash);

// ── 전체 프로젝트 뷰 일괄 갱신 ──
function refreshAllProjectViews() {
  renderDashboardProjects();
  renderProjectsTab();
  renderLeaderBizNav();
  renderMemberProjectMenu();
}


/* ══════════════════════════════════════
   사업비 관리
══════════════════════════════════════ */
// 사업비 데이터 구조: { projId, total, govFund, localFund, executed }
function loadBudgetData() {
  try { return JSON.parse(localStorage.getItem('budget-data') || '{}'); } catch(e) { return {}; }
}
function saveBudgetData(d) { localStorage.setItem('budget-data', JSON.stringify(d)); }

// 집행 내역
function loadExecData() {
  try { return JSON.parse(localStorage.getItem('exec-data') || '[]'); } catch(e) { return []; }
}
function saveExecData(d) { localStorage.setItem('exec-data', JSON.stringify(d)); }

function fmt(n) {
  return Number(n||0).toLocaleString('ko-KR');
}

function renderBudgetMgmt() {
  const budgets = loadBudgetData();
  const execs   = loadExecData();

  // v4 localStorage 예산 동기화: v4-budget-{projId}
  PROJECTS_LIST.forEach(p => {
    const v4key = localStorage.getItem('v4-budget-' + p.id);
    if(v4key) {
      try {
        const v4data = JSON.parse(v4key);
        if(v4data.summary) {
          const b = budgets[p.id] || {};
          // v4 총 예산이 있으면 우선 반영
          if(v4data.summary.total > 0) {
            b.total     = v4data.summary.total;
            b.govFund   = v4data.summary.govFund;
            b.localFund = v4data.summary.localFund;
            budgets[p.id] = b;
          }
          // v4 집행액 반영
          execs = execs.filter(e=>e.projId!==p.id+'_v4');
          if(v4data.summary.executed > 0) {
            execs.push({id:p.id+'_v4', projId:p.id, item:'통합관리 시스템 집행 합계', date:'', amount:v4data.summary.executed, _fromV4:true});
          }
        }
      } catch(e2) {}
    }
  });

  // 사업별 실 집행 합산
  const execByProj = {};
  execs.forEach(e => { execByProj[e.projId] = (execByProj[e.projId]||0) + Number(e.amount||0); });

  // KPI
  let totalBudget=0, totalExec=0;
  PROJECTS_LIST.forEach(p => {
    const b = budgets[p.id] || {};
    totalBudget += Number(b.total||0);
    totalExec   += execByProj[p.id]||0;
  });
  const execRate = totalBudget > 0 ? Math.round(totalExec/totalBudget*100) : 0;
  const remaining = totalBudget - totalExec;

  // 테이블
  const tbody = document.getElementById('budget-tbody');
  if (!tbody) return;

  const PS = { '진행중':'badge-blue','검토중':'badge-gold','완료임박':'badge-green','지연':'badge-red','완료':'badge-gray','계획중':'badge-purple' };

  // 💡 콤마 제거 안전 장치
  const safeNum = (val) => Number(String(val ?? 0).replace(/,/g, '')) || 0;

  // ── 1. 표 본문(행) 그리기 ──
  tbody.innerHTML = PROJECTS_LIST.map(p => {
    // 🚀 [수정] 자부담을 기존 DB에 있던 etc_fund로 매핑합니다!
    const gov = safeNum(p.gov_fund ?? p.govFund);
    const loc = safeNum(p.local_fund ?? p.localFund);
    const etc = safeNum(p.etc_fund ?? p.etcFund); // 자부담(etc)
    
    // 💡 총 예산 합산: 국비 + 지방비 + 자부담(etc)
    const tot = gov + loc + etc; 
    
    const ex = EXEC_LIST
      .filter(e => String(e.projId) === String(p.id))
      .reduce((sum, e) => sum + safeNum(e.amount), 0);
    
    const rem = tot - ex;
    const rt = tot > 0 ? Math.round(ex / tot * 100) : 0;
    const color = rt >= 80 ? 'var(--danger)' : rt >= 50 ? 'var(--gold)' : 'var(--success)';
    
    return `<tr>
      <td style="font-weight:600;color:var(--text)">${p.icon} ${p.name}</td>
      <td><span class="badge ${PS[p.status]||'badge-gray'}">${p.status}</span></td>
      
      <td style="text-align:right;font-family:'DM Mono',monospace;font-weight:600;padding:6px 14px;color:var(--text)">
        ${fmt(tot)}
      </td>
      
      <td><input class="form-input" style="text-align:right;font-family:'DM Mono',monospace;font-size:13px;padding:6px 8px"
          value="${gov?fmt(gov):''}" placeholder="0"
          onchange="updateBudget('${p.id}','govFund',this.value)"
          oninput="this.value=this.value.replace(/[^0-9]/g,'')"></td>
          
      <td><input class="form-input" style="text-align:right;font-family:'DM Mono',monospace;font-size:13px;padding:6px 8px"
          value="${loc?fmt(loc):''}" placeholder="0"
          onchange="updateBudget('${p.id}','localFund',this.value)"
          oninput="this.value=this.value.replace(/[^0-9]/g,'')"></td>
          
      <td><input class="form-input" style="text-align:right;font-family:'DM Mono',monospace;font-size:13px;padding:6px 8px"
          value="${etc?fmt(etc):''}" placeholder="0"
          onchange="updateBudget('${p.id}','etcFund',this.value)"
          oninput="this.value=this.value.replace(/[^0-9]/g,'')"></td>
          
      <td style="font-family:'DM Mono',monospace;font-weight:600;color:var(--text);text-align:right">${fmt(ex)}</td>
      <td style="font-family:'DM Mono',monospace;font-weight:600;color:${rem<0?'var(--danger)':'var(--text)'};text-align:right">${fmt(rem)}</td>
      <td>
        <div class="progress-bar" style="width:80px;margin:0 auto">
          <div class="progress-fill" style="width:${rt}%;background:${color}"></div>
        </div>
        <div style="font-size:11px;text-align:center;color:${color};margin-top:2px;font-weight:600">${rt}%</div>
      </td>
    </tr>`;
  }).join('');

  // ── 2. 합계(tfoot) 및 상단 카드(kpiGrid) 계산 ──
  const sumTotalGov = PROJECTS_LIST.reduce((sum, p) => sum + safeNum(p.gov_fund ?? p.govFund), 0);
  const sumTotalLoc = PROJECTS_LIST.reduce((sum, p) => sum + safeNum(p.local_fund ?? p.localFund), 0);
  const sumTotalEtc = PROJECTS_LIST.reduce((sum, p) => sum + safeNum(p.etc_fund ?? p.etcFund), 0); // 자부담 합계
  
  // 전체 총 예산 합계 (국+지+자)
  const sumTotalBudget = sumTotalGov + sumTotalLoc + sumTotalEtc; 
  
  const sumTotalExec = PROJECTS_LIST.reduce((sum, p) => {
    const pExec = EXEC_LIST
      .filter(e => String(e.projId) === String(p.id))
      .reduce((acc, e) => acc + safeNum(e.amount), 0);
    return sum + pExec;
  }, 0);

  const sumRemaining = sumTotalBudget - sumTotalExec;
  const sumExecRate = sumTotalBudget > 0 ? Math.round((sumTotalExec / sumTotalBudget) * 100) : 0;

  // 하단 표 합계(tfoot) 그리기
  const tfoot = document.getElementById('budget-tfoot');
  if(tfoot) tfoot.innerHTML = `<tr style="background:var(--surface2);font-weight:700">
    <td colspan="2" style="padding:10px 14px;color:var(--text)">합 계</td>
    <td style="font-family:'DM Mono',monospace;text-align:right;padding:10px 10px">${fmt(sumTotalBudget)}</td>
    <td style="font-family:'DM Mono',monospace;text-align:right;padding:10px 10px">${fmt(sumTotalGov)}</td>
    <td style="font-family:'DM Mono',monospace;text-align:right;padding:10px 10px">${fmt(sumTotalLoc)}</td>
    <td style="font-family:'DM Mono',monospace;text-align:right;padding:10px 10px">${fmt(sumTotalEtc)}</td>
    <td style="font-family:'DM Mono',monospace;text-align:right;padding:10px 10px;color:var(--accent)">${fmt(sumTotalExec)}</td>
    <td style="font-family:'DM Mono',monospace;text-align:right;padding:10px 10px">${fmt(sumRemaining)}</td>
    <td></td>
  </tr>`;

  // 상단 요약 카드(kpiGrid) 그리기
  const kpiGrid = document.getElementById('budget-kpi-grid');
  if (kpiGrid) kpiGrid.innerHTML = `
    <div class="stat-card accent-blue"><div class="stat-label">총 예산</div><div class="stat-value" style="font-size:20px">${fmt(sumTotalBudget)}<span class="stat-unit">원</span></div><div class="stat-icon">💰</div></div>
    <div class="stat-card accent-green"><div class="stat-label">총 집행액</div><div class="stat-value" style="font-size:20px">${fmt(sumTotalExec)}<span class="stat-unit">원</span></div><div class="stat-icon">📤</div></div>
    <div class="stat-card accent-gold"><div class="stat-label">잔액</div><div class="stat-value" style="font-size:20px">${fmt(sumRemaining)}<span class="stat-unit">원</span></div><div class="stat-icon">💵</div></div>
    <div class="stat-card accent-purple"><div class="stat-label">집행률</div><div class="stat-value">${sumExecRate}<span class="stat-unit">%</span></div><div class="stat-change ${sumExecRate>80?'down':'up'}">${sumExecRate>80?'⚠ 집행 주의':'정상 범위'}</div><div class="stat-icon">📊</div></div>`;

  // 집행 내역 셀렉트
  const sel = document.getElementById('exec-proj-sel');
  if(sel) sel.innerHTML = PROJECTS_LIST.map(p=>`<option value="${p.id}">${p.name}</option>`).join('');

  // 집행 내역 테이블
  renderExecTable();
}

// 💡 [수정] 표 안의 예산 셀 수정 시, 총 예산도 자동 계산하여 DB에 함께 저장!
async function updateBudget(projId, field, value) {
  const safeNum = (val) => Number(String(val ?? 0).replace(/,/g, '')) || 0;
  const numericValue = safeNum(value);

  let backendField = field;
  if (field === 'total') backendField = 'totalBudget';

  const updateData = {};
  updateData[backendField] = numericValue;

  // 🚀 [핵심 추가] 국비, 지방비, 자부담 중 하나를 수정했다면, 총 예산(totalBudget)도 같이 묶어서 보냅니다!
  const targetProj = PROJECTS_LIST.find(p => p.id === projId);
  if (targetProj) {
    let gov = safeNum(targetProj.gov_fund ?? targetProj.govFund);
    let loc = safeNum(targetProj.local_fund ?? targetProj.localFund);
    let etc = safeNum(targetProj.etc_fund ?? targetProj.etcFund); // 자부담

    // 방금 수정한 최신 값으로 교체
    if (field === 'govFund') gov = numericValue;
    if (field === 'localFund') loc = numericValue;
    if (field === 'etcFund') etc = numericValue; // 자부담(etc)

    // 새로운 총합계를 updateData 꾸러미에 추가
    updateData['totalBudget'] = gov + loc + etc;
  }

  try {
    const res = await fetch(`http://192.168.14.172:8000/projects/${projId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(updateData)
    });

    if (res.ok) {
      showToast('💾 예산이 DB에 저장되었습니다');
      await fetchProjectsFromDB(); 
      if (typeof renderBudgetMgmt === 'function') renderBudgetMgmt();
      if (typeof updateSummaryCards === 'function') updateSummaryCards();
    } else {
      showToast('❌ 서버 저장에 실패했습니다');
    }
  } catch (e) {
    console.error("예산 업데이트 오류:", e);
    showToast('❌ 서버 연결 오류');
  }
}

// 💡 [추가] 서버에서 가져온 집행 내역을 담아둘 전역 변수
let EXEC_LIST = [];

async function fetchExecutionsFromDB() {
  try {
    if (!currentUser) return; // 🚀 [핵심 추가] 로그인 안 했으면 바로 종료!
    const res = await fetch('http://192.168.14.172:8000/executions');
    const data = await res.json();
    
    // DB 데이터를 전역 변수에 저장
    EXEC_LIST = data.map(e => ({
      id: e.id, projId: e.project_id, item: e.item, date: e.date, amount: e.amount
    }));

    // 🚀 데이터가 새로 들어왔으니, 화면 전체(예산 표)를 다시 그리도록 지시!
    if (typeof renderBudgetMgmt === 'function') renderBudgetMgmt(); 
    
  } catch (e) {
    console.error("집행 내역 로드 실패:", e);
  }
}

// ── 1. 집행 내역 추가 (DB에 저장) ──
async function addExecRecord() {
  const projId = document.getElementById('exec-proj-sel')?.value;
  const item   = document.getElementById('exec-item')?.value.trim();
  const date   = document.getElementById('exec-date')?.value;
  const amt    = parseInt(document.getElementById('exec-amt')?.value.replace(/,/g, ''))||0;

  if(!projId||!item) { showToast('⚠️ 항목명을 입력하세요'); return; }
  if(amt<=0) { showToast('⚠️ 금액을 입력하세요'); return; }

  // 백엔드로 보낼 데이터
  const newExec = {
    id: 'ex' + Date.now(),
    projId: projId,
    item: item,
    date: date || new Date().toISOString().slice(0, 10),
    amount: amt
  };

  try {
    const res = await fetch('http://192.168.14.172:8000/executions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(newExec)
    });

    if (res.ok) {
      showToast('📋 집행 내역이 DB에 추가됐습니다');
      document.getElementById('exec-item').value = '';
      document.getElementById('exec-amt').value = '';
      
      // DB에서 전체 데이터를 다시 불러온 후 화면을 갱신합니다.
      await fetchExecutionsFromDB();
      renderBudgetMgmt();
    } else {
      showToast('❌ 서버 저장 실패');
    }
  } catch (e) {
    showToast('❌ 서버 연결 오류');
  }
}

// ── 2. 집행 내역 그리기 (로컬 스토리지 대신 EXEC_LIST 전역 변수 사용) ──
function renderExecTable() {
  const tbody = document.getElementById('exec-tbody');
  if(!tbody) return;
  
  // loadExecData() 대신 서버에서 받아온 EXEC_LIST를 사용합니다.
  const execs = EXEC_LIST; 
  
  if(!execs.length){ 
    tbody.innerHTML='<tr><td colspan="5" style="text-align:center;color:var(--text3);padding:20px">집행 내역이 없습니다</td></tr>'; 
    return; 
  }
  
  tbody.innerHTML = [...execs].reverse().map(e => {
    const p = PROJECTS_LIST.find(x => x.id === e.projId);
    return `<tr>
      <td>${p ? p.icon+' '+p.name : e.projId}</td>
      <td>${e.item}</td>
      <td style="font-family:'DM Mono',monospace">${e.date}</td>
      <td style="text-align:right;font-family:'DM Mono',monospace;font-weight:600">${fmt(e.amount)}</td>
      <td><button class="btn-sm btn-sm-danger" style="padding:4px 8px;font-size:11px" onclick="delExec('${e.id}')">삭제</button></td>
    </tr>`;
  }).join('');
}

// ── 3. 집행 내역 삭제 (DB에서 삭제) ──
async function delExec(id) {
  if(!confirm('이 집행 내역을 DB에서 영구 삭제하시겠습니까?')) return;
  
  try {
    const res = await fetch(`http://192.168.14.172:8000/executions/${id}`, {
      method: 'DELETE'
    });

    if (res.ok) {
      showToast('🗑️ 집행 내역을 삭제했습니다');
      await fetchExecutionsFromDB(); // DB에서 갱신된 데이터를 다시 불러옴
      renderBudgetMgmt();            // 화면 갱신
      renderExecTable();
    } else {
      showToast('❌ 서버 삭제 실패');
    }
  } catch (e) {
    showToast('❌ 서버 연결 오류');
  }
}

function exportBudgetData() {
  const data = { projects: PROJECTS_LIST, budgets: loadBudgetData(), execs: loadExecData() };
  const blob = new Blob([JSON.stringify(data,null,2)], {type:'application/json'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = '사업비_' + new Date().toISOString().slice(0,10) + '.json';
  a.click();
  showToast('📥 사업비 데이터를 내보냈습니다');
}

/* ══════════════════════════════════════
   참여인력 관리
══════════════════════════════════════ */

function loadPersonnelData() {
  try { return JSON.parse(localStorage.getItem('personnel-data') || '{}'); } catch(e) { return {}; }
}
function savePersonnelData(d) { localStorage.setItem('personnel-data', JSON.stringify(d)); }

function renderPersonnelMgmt() {
  const perData = loadPersonnelData();

  // KPI: 전체 배정 인원, 과부하 인원
  let totalAssigned=0, overloaded=0;
  const memberTotal = {};
  TEAM_MEMBERS.forEach(m => { memberTotal[m]=0; });
  Object.values(perData).forEach(projMembers => {
    Object.entries(projMembers).forEach(([name,info]) => {
      if(info.rate>0) { totalAssigned++; memberTotal[name]=(memberTotal[name]||0)+Number(info.rate||0); }
    });
  });
  TEAM_MEMBERS.forEach(m => { if(memberTotal[m]>100) overloaded++; });

  const kpiGrid = document.getElementById('personnel-kpi-grid');
  if(kpiGrid) kpiGrid.innerHTML = `
    <div class="stat-card accent-blue"><div class="stat-label">총 배정 건수</div><div class="stat-value">${totalAssigned}</div><div class="stat-icon">📋</div></div>
    <div class="stat-card accent-cyan" style="border-left:3px solid var(--accent2)"><div class="stat-label">참여 사업 수</div><div class="stat-value">${PROJECTS_LIST.length}</div><div class="stat-icon">📁</div></div>
    <div class="stat-card accent-green"><div class="stat-label">참여 팀원</div><div class="stat-value">${TEAM_MEMBERS.filter(m=>memberTotal[m]>0).length}<span class="stat-unit">명</span></div><div class="stat-icon">👤</div></div>
    <div class="stat-card ${overloaded>0?'accent-purple':'accent-green'}"><div class="stat-label">과부하 인원</div><div class="stat-value" style="color:${overloaded>0?'var(--danger)':'var(--success)'}">${overloaded}<span class="stat-unit">명</span></div><div class="stat-change ${overloaded?'down':'up'}">${overloaded?'⚠ 조정 필요':'정상'}</div><div class="stat-icon">⚡</div></div>`;

  // 사업별 참여인력 카드
  const cardsEl = document.getElementById('personnel-proj-cards');
  if(cardsEl) {
    cardsEl.innerHTML = PROJECTS_LIST.map(p => {
      const pm = perData[p.id] || {};
      const rows = TEAM_MEMBERS.map(name => {
        const info = pm[name] || { rate:0, role:'참여연구원', period:'' };
        return `<tr>
          <td style="font-weight:500">${name}</td>
          <td style="font-size:11px;color:var(--text2)">${MEMBER_DEPT[name]||''}</td>
          <td>
            <select class="form-input" style="padding:4px 6px;font-size:11px"
                    onchange="updatePersonnel('${p.id}','${name}','role',this.value)">
              ${MEMBER_ROLES.map(r=>`<option ${info.role===r?'selected':''}>${r}</option>`).join('')}
            </select>
          </td>
          <td>
            <div style="display:flex;align-items:center;gap:6px">
              <input type="number" class="form-input" min="0" max="100"
                     style="width:60px;text-align:center;padding:4px;font-family:'DM Mono',monospace;font-weight:600"
                     value="${info.rate||0}"
                     onchange="updatePersonnel('${p.id}','${name}','rate',this.value)">
              <span style="font-size:11px;color:var(--text2)">%</span>
              <div class="progress-bar" style="width:60px;height:5px">
                <div class="progress-fill ${Number(info.rate)>=80?'progress-gold':Number(info.rate)>0?'progress-blue':'progress-blue'}"
                     style="width:${Math.min(100,info.rate||0)}%;${Number(info.rate)>=80?'background:var(--gold)':''}"></div>
              </div>
            </div>
          </td>
          <td>
            <input class="form-input" type="text" placeholder="예) 2026.01~06"
                   style="font-size:11px;padding:4px 6px;width:120px"
                   value="${info.period||''}"
                   onchange="updatePersonnel('${p.id}','${name}','period',this.value)">
          </td>
        </tr>`;
      }).join('');
      return `<div class="card" style="margin-bottom:16px">
        <div class="card-header">
          <span class="card-title">${p.icon} ${p.name}</span>
          <span class="badge ${p.ps==='ps-active'?'badge-blue':p.ps==='ps-delay'?'badge-red':p.ps==='ps-done'?'badge-green':'badge-gold'}">${p.status}</span>
        </div>
        <div style="overflow-x:auto">
          <table class="data-table">
            <thead><tr><th style="text-align:left;padding-left:14px">이름</th><th>팀명</th><th>역할</th><th>참여율</th><th>참여기간</th></tr></thead>
            <tbody>${rows}</tbody>
          </table>
        </div>
      </div>`;
    }).join('') || '<div style="text-align:center;padding:40px;color:var(--text3)">등록된 수행사업이 없습니다</div>';
  }

  // 전체 요약 테이블
  const sumTbody = document.getElementById('personnel-summary-tbody');
  if(sumTbody) sumTbody.innerHTML = TEAM_MEMBERS.map(name => {
    const total  = memberTotal[name]||0;
    const cnt    = Object.values(perData).filter(pm=>pm[name]&&pm[name].rate>0).length;
    const status = total>100?'🔴 과부하':total>=80?'🟡 주의':total>0?'🟢 정상':'⚪ 미배정';
    return `<tr>
      <td style="font-weight:600;color:var(--text)">${name}</td>
      <td>${MEMBER_DEPT[name]||''}</td>
      <td style="text-align:center">${cnt}개</td>
      <td>
        <div style="display:flex;align-items:center;gap:8px">
          <div class="progress-bar" style="width:100px;height:7px">
            <div class="progress-fill ${total>100?'progress-red':total>=80?'progress-gold':'progress-blue'}" style="width:${Math.min(100,total)}%"></div>
          </div>
          <span style="font-family:'DM Mono',monospace;font-weight:700;font-size:13px;color:${total>100?'var(--danger)':total>=80?'var(--gold)':'var(--text)'}">${total}%</span>
        </div>
      </td>
      <td>${status}</td>
    </tr>`;
  }).join('');
}

function updatePersonnel(projId, memberName, field, value) {
  const perData = loadPersonnelData();
  if(!perData[projId]) perData[projId] = {};
  if(!perData[projId][memberName]) perData[projId][memberName] = { rate:0, role:'참여연구원', period:'' };
  if(field==='rate') value = Math.min(100, Math.max(0, parseInt(value)||0));
  perData[projId][memberName][field] = value;
  savePersonnelData(perData);
  renderPersonnelMgmt();
}


/* ══════════════════════════════════════
   iframe → team-system 예산 동기화
══════════════════════════════════════ */
window.addEventListener('message', (e) => {
  const { type, projId, summary } = e.data || {};
  if(type === 'budgetUpdated' && projId && summary) {
    // localStorage에 저장 (renderBudgetMgmt가 이미 읽음)
    // summary: { total, govFund, localFund, executed }
    const budgets = loadBudgetData();
    budgets[projId] = Object.assign(budgets[projId]||{}, {
      total:     summary.total,
      govFund:   summary.govFund,
      localFund: summary.localFund,
    });
    saveBudgetData(budgets);
    // 사업비 탭이 열려있으면 즉시 갱신
    const tab = document.getElementById('ltab-budget-mgmt');
    if(tab && tab.style.display !== 'none') renderBudgetMgmt();
  }
});


function changeProjectStatus(projId, newStatus) {
  const proj = PROJECTS_LIST.find(p=>p.id===projId);
  if(!proj) return;
  const PS_MAP = {
    '진행중':'ps-active','검토중':'ps-review','완료임박':'ps-done','지연':'ps-delay','완료':'ps-done','계획중':'ps-review'
  };
  proj.status = newStatus;
  proj.ps     = PS_MAP[newStatus] || 'ps-active';
  saveProjectsList(PROJECTS_LIST);
  refreshAllProjectViews();
  showToast(`📋 '${proj.name}' 상태가 '${newStatus}'로 변경됐습니다`);
}


